def pairwise_wilcoxon(values_a, values_b):
    a, b = np.array(values_a), np.array(values_b)
    if len(a) < 10 or np.allclose(a, b):
        return {"statistic": float("nan"), "p_value": 1.0}
    try:
        stat, p = wilcoxon(a, b, alternative="two-sided")
        return {"statistic": float(stat), "p_value": float(p)}
    except ValueError:
        return {"statistic": float("nan"), "p_value": 1.0}


